INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload)
SELECT 'core-2026-09-v4','future-perfect-continuous','87b630c771d79eac83e3be02f06e226cf9455e201ca4d4e9ebd574542396373d',payload || '{"slug":"future-perfect-continuous","title":"Future continuous and future perfect","level":"B2","order":34,"summary":"Look ahead to an activity in progress, a completed result or a duration measured from a future point.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["An activity at a future moment","Completion by a future deadline","Duration up to a future point","Questions and negatives"],"rules":[{"title":"An activity at a future moment","explanation":"Use **will be + -ing** to picture an activity already in progress at a future moment. You are looking into the middle of it. This differs from will + base verb, which can simply predict an event or express a decision.","pattern":"At noon, we **will be travelling**.","commonMistakes":["A precise future time does not always require continuous; the intended viewpoint decides."],"examples":["Use future continuous: At ten tomorrow, we **will be preparing** the visitor guide.","Use future continuous: At ten tomorrow, we **will be restoring** the old portrait."],"skill":"form"},{"title":"Completion by a future deadline","explanation":"Use **will have + past participle** to look back from a future point at something expected to be complete. By means no later than that point. Until generally describes continuation up to a point, so it is not interchangeable with by.","pattern":"By noon, we **will have arrived**.","commonMistakes":["Will have arrived describes completion by a deadline; will arrive until noon does not express that meaning."],"examples":["Use future perfect simple: By Friday, they **will have prepared** the visitor guide.","Use future perfect simple: By Friday, they **will have restored** the old portrait."],"skill":"meaning"},{"title":"Duration up to a future point","explanation":"Use **will have been + -ing** for the duration of an activity measured at a future point. It combines future reference, perfect aspect and continuous aspect. The first auxiliary is will; the later forms stay have and been.","pattern":"By July, I **will have been working** here for a year.","commonMistakes":["State verbs usually favour future perfect simple: will have known, rather than will have been knowing."],"examples":["Use future perfect continuous: By noon, I **will have been preparing** the visitor guide for two hours.","Use future perfect continuous: By noon, I **will have been restoring** the old portrait for two hours."],"skill":"contrast"},{"title":"Questions and negatives","explanation":"Move **will** before the subject in a question. Put **not** after will in a negative. All later auxiliaries stay after the subject in their original order. In conversation, will not often becomes won’t.","pattern":"Will she **have finished**? / She **will not have finished**.","commonMistakes":["Do not change have to has after will, even with she, he or it."],"examples":["Choose the opening for a future-perfect question about the visitor guide: **Will** they have prepared it by Friday?","Choose the opening for a future-perfect question about the old portrait: **Will** they have restored it by Friday?"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-future-perfect"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"chapter":{"introduction":["Look ahead to an activity in progress, a completed result or a duration measured from a future point.","The form tells you how to build the sentence; the context tells you why that form is useful. Read each section with both questions in mind. The examples make one contrast at a time, while the practice mixes the skills so that you learn to recognise the pattern yourself."],"rules":[{"title":"An activity at a future moment","explanation":"Use **will be + -ing** to picture an activity already in progress at a future moment. You are looking into the middle of it. This differs from will + base verb, which can simply predict an event or express a decision.","pattern":"At noon, we **will be travelling**.","commonMistakes":["A precise future time does not always require continuous; the intended viewpoint decides."],"examples":["Use future continuous: At ten tomorrow, we **will be preparing** the visitor guide.","Use future continuous: At ten tomorrow, we **will be restoring** the old portrait."],"skill":"form","id":"future-perfect-continuous-foundation-1","domain":"verbs","referenceIds":["bc-future-perfect"],"readingVersion":"core-2026-09-v3"},{"title":"Completion by a future deadline","explanation":"Use **will have + past participle** to look back from a future point at something expected to be complete. By means no later than that point. Until generally describes continuation up to a point, so it is not interchangeable with by.","pattern":"By noon, we **will have arrived**.","commonMistakes":["Will have arrived describes completion by a deadline; will arrive until noon does not express that meaning."],"examples":["Use future perfect simple: By Friday, they **will have prepared** the visitor guide.","Use future perfect simple: By Friday, they **will have restored** the old portrait."],"skill":"meaning","id":"future-perfect-continuous-foundation-2","domain":"verbs","referenceIds":["bc-future-perfect"],"readingVersion":"core-2026-09-v3"},{"title":"Duration up to a future point","explanation":"Use **will have been + -ing** for the duration of an activity measured at a future point. It combines future reference, perfect aspect and continuous aspect. The first auxiliary is will; the later forms stay have and been.","pattern":"By July, I **will have been working** here for a year.","commonMistakes":["State verbs usually favour future perfect simple: will have known, rather than will have been knowing."],"examples":["Use future perfect continuous: By noon, I **will have been preparing** the visitor guide for two hours.","Use future perfect continuous: By noon, I **will have been restoring** the old portrait for two hours."],"skill":"contrast","id":"future-perfect-continuous-foundation-3","domain":"verbs","referenceIds":["bc-future-perfect"],"readingVersion":"core-2026-09-v3"},{"title":"Questions and negatives","explanation":"Move **will** before the subject in a question. Put **not** after will in a negative. All later auxiliaries stay after the subject in their original order. In conversation, will not often becomes won’t.","pattern":"Will she **have finished**? / She **will not have finished**.","commonMistakes":["Do not change have to has after will, even with she, he or it."],"examples":["Choose the opening for a future-perfect question about the visitor guide: **Will** they have prepared it by Friday?","Choose the opening for a future-perfect question about the old portrait: **Will** they have restored it by Friday?"],"skill":"application","id":"future-perfect-continuous-foundation-4","domain":"verbs","referenceIds":["bc-future-perfect"],"readingVersion":"core-2026-09-v3"}],"recap":["At noon, we **will be travelling**.","By noon, we **will have arrived**.","By July, I **will have been working** here for a year.","Will she **have finished**? / She **will not have finished**."],"readingVersion":"core-2026-09-v4"},"stage":"3 · Time and experience","prerequisites":["past-perfect-continuous"],"readingReferenceIds":["bc-future-perfect"]}'::jsonb FROM grammar.content_catalog_topics WHERE version='core-2026-09-v3' AND slug='future-perfect-continuous'
